import { describe, expect, it } from 'vitest';
import { HadamardPower, HadamardProduct, Identity, Matrix, MatrixElement, MatrixSymbol, OneMatrix, ShapeError, Sym, ZeroMatrix, canonicalize, hadamardPower, hadamardProduct, rational, symbols } from '../../../src';
import { sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.matrices.expressions.hadamard", () => {
  it("hadamard_product(A)", () => {
    expect(sympyStr(hadamardProduct(new MatrixSymbol('A', rational(2), rational(3))))).toBe('A');
  });
  it("hadamard_product(A, B)", () => {
    expect(sympyStr(hadamardProduct(new MatrixSymbol('A', rational(2), rational(3)), new MatrixSymbol('B', rational(2), rational(3))))).toBe('HadamardProduct(A, B)');
  });
  // the arguments do not type-check against the public API
  //   hadamard_product(A, B)[0, 1]
  //   => A[0, 1]*B[0, 1]
  it.todo("hadamard_product(A, B)[0, 1]");
  it("canonicalize(X)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), HadamardProduct(new MatrixSymbol('B', rational(2), rational(2)), new MatrixSymbol('C', rational(2), rational(2))))))).toBe('HadamardProduct(A, B, C)');
  });
  it("canonicalize(X) (2)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), new MatrixSymbol('B', rational(2), rational(2)))))).toBe('HadamardProduct(A, B)');
  });
  it("canonicalize(Y)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('B', rational(2), rational(2)), new MatrixSymbol('A', rational(2), rational(2)))))).toBe('HadamardProduct(A, B)');
  });
  it("canonicalize(X) (3)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), OneMatrix(rational(2), rational(2)))))).toBe('A');
  });
  it("canonicalize(X) (4)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), ZeroMatrix(rational(2), rational(2)))))).toBe('0');
  });
  it("canonicalize(X) (5)", () => {
    expect(sympyStr(canonicalize(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), new MatrixSymbol('A', rational(2), rational(2)), new MatrixSymbol('A', rational(2), rational(2)))))).toBe('HadamardPower(A, 3)');
  });
  it("X", () => {
    expect(sympyStr(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), HadamardProduct(new MatrixSymbol('B', rational(2), rational(2)), new MatrixSymbol('C', rational(2), rational(2)))))).toBe('HadamardProduct(A, HadamardProduct(B, C))');
  });
  it("X (2)", () => {
    expect(sympyStr(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), OneMatrix(rational(2), rational(2))))).toBe('HadamardProduct(A, 1)');
  });
  it("X (3)", () => {
    expect(sympyStr(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), ZeroMatrix(rational(2), rational(2))))).toBe('HadamardProduct(A, 0)');
  });
  it("X (4)", () => {
    expect(sympyStr(HadamardProduct(new MatrixSymbol('A', rational(2), rational(2)), new MatrixSymbol('A', rational(2), rational(2)), new MatrixSymbol('A', rational(2), rational(2))))).toBe('HadamardProduct(A, A, A)');
  });
});

